package com.yonlab.vision;
import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
import com.google.zxing.*;import com.google.zxing.common.BitMatrix;import org.junit.Test;import static org.junit.Assert.*;
public class ToolsPolicyTest {
 private Observations.Detection d(int id,String label,float score){return new Observations.Detection(id,label,score,.1f,.2f,.8f,.9f);}
 private static final class Nodes implements BoardLed.NodeIo {final Map<String,String> values=new HashMap<>();final List<String>writes=new ArrayList<>();boolean noBlink,changeTrigger;String failOnce;AtomicBoolean cancel;
  Nodes(boolean missingBlink){noBlink=missingBlink;for(int i=0;i<3;i++){values.put(BoardLed.PATHS[i],"0");values.put(BoardLed.BRIGHTNESS[i],"0");values.put(BoardLed.MAX[i],"255");values.put(BoardLed.TRIGGER[i],"[none] timer heartbeat");}}
  public String read(String p)throws IOException{if(noBlink&&Arrays.asList(BoardLed.PATHS).contains(p))throw new IOException("EIO");if(!values.containsKey(p))throw new IOException("unknown path");return values.get(p);}
  public void write(String p,String v)throws IOException{assertTrue(Arrays.asList(BoardLed.PATHS).contains(p)||Arrays.asList(BoardLed.BRIGHTNESS).contains(p));writes.add(p+"="+v);if(p.equals(failOnce)){failOnce=null;throw new IOException("denied");}values.put(p,v);if(cancel!=null)cancel.set(false);if(changeTrigger&&p.equals(BoardLed.BRIGHTNESS[0])){changeTrigger=false;values.put(BoardLed.TRIGGER[0],"none [timer]");}}
 }
 @Test public void qrUtf8PayloadRoundtripsWithoutLaunchingAnything()throws Exception{String text="YOnLab · 한글\nhttps://example.com/?q=1&x=2";int[] pixels=BarcodeHelper.qr(text,512);BarcodeHelper.Decoded decoded=BarcodeHelper.decode(pixels,512,512);assertEquals(text,decoded.text);assertEquals("QR_CODE",decoded.format);}
 @Test public void code128PortraitRotationIsActuallyDecoded()throws Exception{BitMatrix m=new MultiFormatWriter().encode("YON-42",BarcodeFormat.CODE_128,384,96);int[] pixels=new int[384*96];for(int y=0;y<96;y++)for(int x=0;x<384;x++)pixels[x*96+(95-y)]=m.get(x,y)?0xff000000:0xffffffff;assertEquals("YON-42",BarcodeHelper.decode(pixels,96,384).text);}
 @Test(expected=NotFoundException.class)public void blankQrPhotoIsNotSuccess()throws Exception{int[] blank=new int[120*80];Arrays.fill(blank,0xffffffff);BarcodeHelper.decode(blank,120,80);}
 @Test(expected=IllegalArgumentException.class)public void qrDimensionsAreBounded()throws Exception{BarcodeHelper.decode(new int[1],1,5000000);}
 @Test public void petUsesActualSparseCocoLabelsAndPreservesScore(){Observations.Detection dog=d(17,"dog",.83f),cat=d(16,"cat",.71f),car=d(16,"car",.99f);List<Observations.Detection> selected=ToolFilters.select(Arrays.asList(dog,cat,car),"pet");assertEquals(2,selected.size());assertSame(dog,selected.get(0));assertEquals(.83f,selected.get(0).score,0);}
 @Test public void sportsBallIsNotGuessedFromClassId(){assertEquals(1,ToolFilters.select(Arrays.asList(d(36,"sports ball",.8f),d(32,"tie",.99f)),"ball").size());}
 @Test public void invalidOrLowScoresDoNotBecomePets(){Observations.Detection bad=d(17,"dog",.9f);bad.right=Float.NaN;assertTrue(ToolFilters.select(Arrays.asList(bad,d(17,"dog",.39f),d(17,"dog",Float.NaN)),"pet").isEmpty());}
 @Test public void poseDoesNotInventMissingOrUnconfidentJoints(){List<PoseGeometry.Point> points=Arrays.asList(new PoseGeometry.Point(11,.2f,.3f,.9f),new PoseGeometry.Point(12,.7f,.3f,.8f),new PoseGeometry.Point(13,.1f,.5f,.2f),new PoseGeometry.Point(14,Float.NaN,.5f,1));assertEquals(2,PoseGeometry.visible(points).size());assertEquals(1,PoseGeometry.edges(points).size());}
 @Test public void poseOutsideFrameIsNotClampedIntoVisibility(){assertFalse(PoseGeometry.visible(new PoseGeometry.Point(11,-.01f,.3f,.9f)));assertFalse(PoseGeometry.visible(new PoseGeometry.Point(33,.1f,.3f,.9f)));}
 @Test public void blinkSnapshotsAndRestoresOriginalValues(){Nodes n=new Nodes(false);BoardLed led=new BoardLed(n);assertEquals("APPLIED",led.set(true).status);assertEquals("1",n.values.get(BoardLed.PATHS[0]));assertEquals("RESTORED",led.restore().status);for(String p:BoardLed.PATHS)assertEquals("0",n.values.get(p));}
 @Test public void brightnessFallbackRequiresNoneAndRestoresRgb(){Nodes n=new Nodes(true);BoardLed led=new BoardLed(n);BoardLed.Report on=led.set(true);assertEquals("APPLIED",on.status);assertEquals("brightness",on.backend);assertTrue(on.fallbackReason.contains("EIO"));for(String p:BoardLed.BRIGHTNESS)assertEquals("255",n.values.get(p));assertEquals(3,on.dirtyCount);assertEquals("RESTORED",led.restore().status);for(String p:BoardLed.BRIGHTNESS)assertEquals("0",n.values.get(p));}
 @Test public void activeTriggerFailsBeforeAnyWrite(){Nodes n=new Nodes(true);n.values.put(BoardLed.TRIGGER[1],"none [timer]");BoardLed.Report result=new BoardLed(n).set(true);assertEquals("FAILED",result.status);assertTrue(n.writes.isEmpty());assertEquals(0,result.dirtyCount);}
 @Test public void partialWriteFailureRestoresOriginals(){Nodes n=new Nodes(false);n.failOnce=BoardLed.PATHS[1];BoardLed.Report result=new BoardLed(n).set(true);assertEquals("FAILED",result.status);assertEquals(0,result.dirtyCount);for(String p:BoardLed.PATHS)assertEquals("0",n.values.get(p));}
 @Test public void triggerChangeDoesNotOverwriteTheExternalTrigger(){Nodes n=new Nodes(true);n.changeTrigger=true;BoardLed led=new BoardLed(n);BoardLed.Report result=led.set(true);assertEquals("FAILED",result.status);assertEquals(1,result.dirtyCount);assertEquals("none [timer]",n.values.get(BoardLed.TRIGGER[0]));n.values.put(BoardLed.TRIGGER[0],"[none] timer");assertEquals("RESTORED",led.restore().status);assertEquals("0",n.values.get(BoardLed.BRIGHTNESS[0]));}
 @Test public void staleScreenCannotUndoNewOwner(){Nodes n=new Nodes(false);BoardLedController controller=new BoardLedController(new BoardLed(n));AtomicBoolean a=new AtomicBoolean(true),b=new AtomicBoolean(true);controller.set(1,a,true);a.set(false);assertEquals("APPLIED",controller.set(2,b,true).status);assertEquals("STALE_OWNER_IGNORED",controller.restore(1).status);assertEquals("1",n.values.get(BoardLed.PATHS[0]));b.set(false);assertEquals("RESTORED",controller.restoreInactive().status);assertEquals("0",n.values.get(BoardLed.PATHS[0]));}
 @Test public void cancellationDuringSetRestoresBeforeReturning(){Nodes n=new Nodes(false);AtomicBoolean alive=new AtomicBoolean(true);n.cancel=alive;BoardLed.Report result=new BoardLedController(new BoardLed(n)).set(7,alive,true);assertEquals("RESTORED",result.status);assertEquals(0,result.dirtyCount);for(String p:BoardLed.PATHS)assertEquals("0",n.values.get(p));}
}
